        },
    }


def hook_state(root: Path, plugin_root: Path, hook_source: str) -> dict[str, Any]:
    plugin_hooks = plugin_root / "hooks" / "hooks.json"
    effective_plugin = plugin_hooks.is_file()
    events: list[str] = []
    if effective_plugin:
        data = json.loads(plugin_hooks.read_text(encoding="utf-8"))
        events = sorted((data.get("hooks") or {}).keys())
    settings = root / ".claude" / "settings.json"
    project_entries = 0
    if settings.is_file():
        raw = settings.read_text(encoding="utf-8")
        project_entries = raw.count("dev-graph")
    state = {
        "mode": hook_source,
        "effective_plugin_hook": "hooks/hooks.json" if effective_plugin else None,
        "effective_source": "hooks/hooks.json" if hook_source == "plugin" and effective_plugin else None,
        "required_events": sorted(REQUIRED_HOOK_EVENTS),
        "plugin_events": events,
        "project_settings_present": settings.is_file(),
        "project_dev_graph_registrations": project_entries,
        "duplicate_count": 0,
        "settings_write": "none",
    }
    diagnostics: list[str] = []
    if hook_source == "plugin":
        if not effective_plugin:
            diagnostics.append("plugin_hook_missing")
        if set(events) != set(REQUIRED_HOOK_EVENTS):
            diagnostics.append(f"plugin_hook_event_mismatch:{events}")
        if project_entries:
            state["duplicate_count"] = project_entries
            diagnostics.append("project_fallback_already_registered")
    else:
        if effective_plugin:
            diagnostics.append("project_fallback_rejected_effective_plugin_hook_present")
    state["diagnostics"] = diagnostics
    state["valid"] = not diagnostics
    return state


def gh_auth() -> dict[str, Any]:
    if shutil.which("gh") is None:
        return {"available": False, "authenticated": False, "status": "gh_cli_not_installed", "exit_code": None}
    cp = subprocess.run(["gh", "auth", "status"], text=True, capture_output=True, check=False)
    return {
        "available": True,
        "authenticated": cp.returncode == 0,
        "status": "authenticated" if cp.returncode == 0 else "not_authenticated",
        "exit_code": cp.returncode,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root", required=True)
    parser.add_argument("--hook-source", choices=("plugin", "project-fallback"), default="plugin")
    parser.add_argument("--plugin-root", required=True)
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--report")
    args = parser.parse_args()

    plugin_root = Path(args.plugin_root).resolve(strict=True)
    scripts = plugin_root / "scripts"

    # Step 1: C24 context receipt (write mode).
    cp = subprocess.run(
        [sys.executable, str(scripts / "resolve-repo-context.py"), "--repo-root", args.repo_root, "--mode", "write"],
        text=True, capture_output=True, check=False, cwd=str(scripts),
    )
    if cp.returncode != 0:
        print(cp.stderr.strip(), file=sys.stderr)
        return 2
    context = json.loads(cp.stdout)
    root = Path(context["repo_root"])
    if root.resolve(strict=True) != Path(context["content_roots"]["repository"]).resolve(strict=True):
        print("repo_root does not match content_roots.repository", file=sys.stderr)
        return 2
    repository_id = context["repository_id"]

    validator_module = load_module(scripts / "validate-graph-schema.py", "dg_validate")
    repo_config_schema = json.loads((plugin_root / "schemas" / "repo-config.schema.json").read_text(encoding="utf-8"))
    template_contract = json.loads((plugin_root / "templates" / "template-contract.json").read_text(encoding="utf-8"))

    config_value = desired_config(repository_id, root.name, args.hook_source)
    graph_value = {"schema_version": "1.0.0", "graph_revision": 0, "nodes": []}

    planned: list[dict[str, str]] = []
    created: list[str] = []
    preserved: list[str] = []
    migration_preview: list[dict[str, str]] = []

    directories = [CONTENT_ROOTS[key] for key in sorted(CONTENT_ROOTS)] + [
        ".dev-graph", ".dev-graph/state", LOCAL_STATE["cache"], LOCAL_STATE["locks"], TEMPLATES_REL,
    ]
    for relative in directories:
        target = root / relative
        if target.is_dir():
            preserved.append(relative + "/")
        else:
            planned.append({"path": relative + "/", "action": "mkdir"})

    def plan_json(relative: str, value: Any) -> None:
        target = root / relative
        if not target.exists():
            planned.append({"path": relative, "action": "create"})
            return
        current = target.read_bytes()
        if current == canonical_bytes(value):
            preserved.append(relative)
        else:
            preserved.append(relative)
            migration_preview.append({
                "path": relative,
                "reason": "user_modified",
                "current_sha256": hashlib.sha256(current).hexdigest(),
                "plugin_sha256": hashlib.sha256(canonical_bytes(value)).hexdigest(),
            })

    plan_json(".dev-graph/config.json", config_value)
    plan_json(LOCAL_STATE["graph"], graph_value)

    template_sources = sorted(p for p in (plugin_root / "templates").rglob("*") if p.is_file())
    for source in template_sources:
        relative = f"{TEMPLATES_REL}/{source.relative_to(plugin_root / 'templates').as_posix()}"
        target = root / relative
        if not target.exists():
            planned.append({"path": relative, "action": "copy"})
            continue
        current, origin = sha256_file(target), sha256_file(source)
        preserved.append(relative)
        if current != origin:
            migration_preview.append({
                "path": relative, "reason": "user_modified",
                "current_sha256": current, "plugin_sha256": origin,
            })

    hooks = hook_state(root, plugin_root, args.hook_source)
    receipt_exists = (root / RECEIPT_REL).is_file()
    if not receipt_exists:
        planned.append({"path": RECEIPT_REL, "action": "create"})
    else:
        preserved.append(RECEIPT_REL)

    applied: list[str] = []
    if not args.dry_run:
        if not hooks["valid"]:
            print(f"hook wiring rejected: {hooks['diagnostics']}", file=sys.stderr)
            return 2
        for change in planned:
            relative, action = change["path"], change["action"]
            if action == "mkdir":
                (root / relative.rstrip("/")).mkdir(parents=True, exist_ok=True)
            elif action == "copy":
                source = plugin_root / "templates" / Path(relative).relative_to(TEMPLATES_REL)
                target = root / relative
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(source, target)
            elif action == "create" and relative != RECEIPT_REL:
                target = root / relative
                target.parent.mkdir(parents=True, exist_ok=True)
                value = config_value if relative.endswith("config.json") else graph_value
                target.write_bytes(canonical_bytes(value))
            applied.append(relative)
            created.append(relative)

    # Step 5: C11 / schema gate.
    config_on_disk = json.loads((root / ".dev-graph/config.json").read_text(encoding="utf-8"))
    config_errors = schema_errors(config_on_disk, repo_config_schema, validator_module)
    if config_on_disk.get("repository_id") != repository_id:
        config_errors.append("$.repository_id: does not match C24 derived repository")

    absolute_paths = [
        f"{trail}={value}" for trail, value in walk_strings(config_on_disk)
        if value.startswith("/") or value.startswith("~") or str(root) in value or str(plugin_root) in value
    ]
    secret_findings = [trail for trail, key in walk_keys(config_on_disk) if key.lower() in SECRET_KEYS]
    secret_findings += [f"{trail}={value[:8]}" for trail, value in walk_strings(config_on_disk) if SECRET_VALUE.match(value)]

    graph_path = root / LOCAL_STATE["graph"]
    gate = subprocess.run(
        [sys.executable, str(scripts / "validate-graph-schema.py"), "--graph", str(graph_path), "--repo-root", str(root)],
        text=True, capture_output=True, check=False, cwd=str(scripts),
    )
    graph_report = json.loads(gate.stdout) if gate.stdout.strip() else {"valid": False, "stderr": gate.stderr.strip()}

    contract_templates = {template_contract["common_frontmatter"]["template"]}
    for artifact in template_contract["artifacts"].values():
        contract_templates.add(artifact["template"])
        contract_templates.update((artifact.get("subtype_templates") or {}).values())
        contract_templates.update((artifact.get("conditional_templates") or {}).values())
    contract_templates.add(template_contract["graph_projection"]["template"])
    contract_templates.add(template_contract["system_plan"]["task_overlay"])
    contract_templates.add("template-contract.json")
    missing_templates = sorted(
        name for name in contract_templates if not (root / TEMPLATES_REL / name).is_file()
    )
    template_count = sum(1 for p in (root / TEMPLATES_REL).rglob("*") if p.is_file())

    content_root_state = {
        key: (root / value).is_dir() for key, value in sorted(CONTENT_ROOTS.items())
    }
    local_state_state = {
        "config": (root / ".dev-graph/config.json").is_file(),
        "graph": graph_path.is_file(),
        "cache": (root / LOCAL_STATE["cache"]).is_dir(),
        "locks": (root / LOCAL_STATE["locks"]).is_dir(),
        "templates": (root / TEMPLATES_REL).is_dir(),
    }

    schema_result = {
        "repo_config": {"schema": "schemas/repo-config.schema.json", "valid": not config_errors, "violations": config_errors},
        "graph": {
            "schema": "schemas/graph-node.schema.json",
            "valid": bool(graph_report.get("valid")),
            "exit_code": gate.returncode,
            "missing_sections": graph_report.get("missing_sections", []),
            "violations": graph_report.get("violations", []),
        },
        "templates": {"count": template_count, "missing": missing_templates, "valid": not missing_templates},
        "claude_hooks": hooks,
        "path_policy": {"absolute_stored_paths": absolute_paths, "valid": not absolute_paths},
        "secrets": {"findings": secret_findings, "valid": not secret_findings},
    }
    all_valid = all(section["valid"] for section in schema_result.values()) and all(content_root_state.values()) and all(local_state_state.values())

    receipt = {
        "schema_version": "1.0.0",
        "owner": "C01/run-dev-graph-init",
        "status": "initialized" if all_valid else "failed",
        "repository_id": repository_id,
        "content_roots": dict(CONTENT_ROOTS),
        "local_state": dict(LOCAL_STATE),
        "created": sorted(created),
        "preserved": sorted(preserved),
        "migration_preview": migration_preview,
        "hook_source": args.hook_source,
        "hook_result": hooks,
        "gh_cli_auth": gh_auth(),
        "schema_result": schema_result,
    }
    if not args.dry_run and not receipt_exists and all_valid:
        (root / RECEIPT_REL).write_bytes(canonical_bytes(receipt))

    report = {
        "dry_run": args.dry_run,
        "repo_root_relative_only": True,
        "repository_id": repository_id,
        "planned_changes": planned,
        "planned_change_count": len(planned),
        "applied": sorted(applied),
        "preserved_count": len(preserved),
        "migration_preview": migration_preview,
        "content_roots_present": content_root_state,
        "local_state_present": local_state_state,
        "receipt_path": RECEIPT_REL,
        "receipt_written_this_run": bool(not args.dry_run and not receipt_exists and all_valid),
        "schema_result": schema_result,
        "gh_cli_auth": receipt["gh_cli_auth"],
        "valid": all_valid,
    }
    text = json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2)
    print(text)
    if args.report:
        Path(args.report).write_text(text + "\n", encoding="utf-8")
    return 0 if all_valid else 1


if __name__ == "__main__":
    raise SystemExit(main())

